 LinearLayout root,body,nav;SurfaceView surface;FrameLayout preview;Camera camera;EditText input;ImageView output;Bitmap generated;String draft="";int page=0;boolean resumed=false,ready=false,torch=false,cameraRequested=false,resultShowing=false,permissionAsked=false;volatile boolean scanning=false,busy=false;long lastFrame=0;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());JSONArray history=new JSONArray();
