 void scannerPage(){cameraRequested=true;body.addView(text("Сканирование QR",21,INK));body.addView(text("Помести код в рамку — результат появится здесь.",14,MUTED));preview=new FrameLayout(this);preview.setBackground(shape(CARD,20));preview.setClipToOutline(true);body.addView(preview,new LinearLayout.LayoutParams(-1,dp(300)));surface=new SurfaceView(this);surface.getHolder().addCallback(this);preview.addView(surface,new FrameLayout.LayoutParams(-1,-1));preview.addView(new Reticle(),new FrameLayout.LayoutParams(-1,-1));body.addView(button("Выбрать QR с картинки",false,()->{scanning=false;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);}));body.addView(button("Фонарик: вкл. / выкл.",false,()->toggleTorch()));body.addView(text("Разрешение камеры нужно только для сканирования. Ссылки открываются по твоему нажатию.",12,MUTED));}
 void generatorPage(){body.addView(text("Создать QR-код",21,INK));body.addView(text("Введи текст или полную ссылку https://…",14,MUTED));input=new EditText(this);input.setTextColor(INK);input.setHintTextColor(MUTED);input.setHint("Текст или ссылка");input.setText(draft);input.setGravity(Gravity.TOP);input.setMinLines(3);input.setMaxLines(6);input.setPadding(dp(14),dp(12),dp(14),dp(12));input.setBackground(shape(CARD,14));body.addView(input,new LinearLayout.LayoutParams(-1,dp(125)));body.addView(button("Создать QR",true,()->generate()));output=new ImageView(this);output.setAdjustViewBounds(true);output.setScaleType(ImageView.ScaleType.FIT_CENTER);output.setPadding(dp(8),dp(8),dp(8),dp(8));if(generated!=null){output.setImageBitmap(generated);output.setBackground(shape(0xffffffff,16));}LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(-1,dp(285));op.setMargins(0,dp(14),0,dp(8));body.addView(output,op);body.addView(button("Сохранить PNG",false,()->save()));body.addView(button("Поделиться QR",false,()->share()));}
 void generate(){String value=input.getText().toString();if(value.trim().isEmpty()){toast("Введи текст или ссылку");return;}try{BitMatrix m=QrEngine.encode(value);int w=m.getWidth();int[] pixels=new int[w*w];for(int y=0;y<w;y++)for(int x=0;x<w;x++)pixels[y*w+x]=m.get(x,y)?0xff000000:0xffffffff;generated=Bitmap.createBitmap(pixels,w,w,Bitmap.Config.ARGB_8888);output.setImageBitmap(generated);output.setBackground(shape(0xffffffff,16));((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);}catch(Exception e){toast("Слишком большой текст для QR. Сократи его.");}}
 void save(){if(generated==null){toast("Сначала создай QR");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("image/png");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"QR-Studio.png");startActivityForResult(i,11);}
 void share(){if(generated==null){toast("Сначала создай QR");return;}try{try(FileOutputStream f=new FileOutputStream(new File(getCacheDir(),"qr.png"))){generated.compress(Bitmap.CompressFormat.PNG,100,f);}Uri u=Uri.parse("content://ru.colpak.qrstudio.share/qr.png");Intent i=new Intent(Intent.ACTION_SEND);i.setType("image/png");i.putExtra(Intent.EXTRA_STREAM,u);i.setClipData(ClipData.newRawUri("QR",u));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Поделиться QR"));}catch(Exception e){toast("Не удалось поделиться QR");}}
 void historyPage(){body.addView(text("История сканирований",21,INK));body.addView(text("Последние 30 кодов хранятся на этом устройстве.",13,MUTED));if(history.length()==0)body.addView(text("Пока пусто. Отсканируй первый QR-код.",16,MUTED));for(int j=0;j<history.length();j++){JSONObject o=history.optJSONObject(j);if(o==null)continue;String val=o.optString("text");LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(10),dp(14),dp(10));card.setBackground(shape(CARD,14));TextView t=text(val,15,INK);t.setMaxLines(3);t.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(t);card.addView(text(o.optString("date"),11,MUTED));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,0);body.addView(card,p);card.setOnClickListener(v->showResult(val,false));}if(history.length()>0)body.addView(button("Очистить историю",false,()->new AlertDialog.Builder(this).setTitle("Очистить историю?").setMessage("Все сохранённые результаты будут удалены.").setNegativeButton("Отмена",null).setPositiveButton("Очистить",(d,w)->{history=new JSONArray();persist();showPage(2);}).show()));}
 void persist(){getPreferences(0).edit().putString("history",history.toString()).apply();}
 void showResult(String value,boolean record){scanning=false;resultShowing=true;if(record){JSONArray arr=new JSONArray();try{JSONObject o=new JSONObject();o.put("text",value);o.put("date",new java.text.SimpleDateFormat("dd.MM.yyyy · HH:mm",Locale.getDefault()).format(new Date()));arr.put(o);for(int j=0;j<history.length()&&arr.length()<30;j++)if(!value.equals(history.getJSONObject(j).optString("text")))arr.put(history.getJSONObject(j));history=arr;persist();}catch(Exception ignored){}}
 LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(20),0,dp(20),0);TextView content=text(value,17,INK);content.setTextIsSelectable(true);ScrollView sv=new ScrollView(this);sv.addView(content);box.addView(sv,new LinearLayout.LayoutParams(-1,dp(240)));String url=QrEngine.webUrl(value);if(url!=null)box.addView(text("Ссылка: "+Uri.parse(url).getHost(),13,MUTED));AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle("QR отсканирован").setView(box).setNegativeButton("Закрыть",null).setNeutralButton("Копировать",null);if(url!=null)b.setPositiveButton("Перейти",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){toast("Нет приложения для открытия ссылки");}});AlertDialog d=b.create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(k->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("QR",value));toast("Текст скопирован");}));d.setOnDismissListener(v->{resultShowing=false;lastFrame=SystemClock.elapsedRealtime()+1000;if(page==0&&resumed){scanning=true;ensureCamera();}});d.show();}
 void ensureCamera(){if(page!=0||!resumed||resultShowing)return;cameraRequested=true;if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){if(!permissionAsked){permissionAsked=true;requestPermissions(new String[]{Manifest.permission.CAMERA},20);}return;}if(ready){if(camera==null)startCamera();else scanning=true;}}
 void startCamera(){try{int id=-1;Camera.CameraInfo info=new Camera.CameraInfo();for(int j=0;j<Camera.getNumberOfCameras();j++){Camera.getCameraInfo(j,info);if(info.facing==Camera.CameraInfo.CAMERA_FACING_BACK){id=j;break;}}if(id<0){toast("Основная камера не найдена. Выбери картинку.");return;}camera=Camera.open(id);Camera.getCameraInfo(id,info);Camera.Parameters p=camera.getParameters();Camera.Size best=null;for(Camera.Size s:p.getSupportedPreviewSizes())if(s.width<=1280&&(best==null||s.width*s.height>best.width*best.height))best=s;if(best!=null)p.setPreviewSize(best.width,best.height);if(p.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);p.setPreviewFormat(ImageFormat.NV21);camera.setParameters(p);int rotation=getWindowManager().getDefaultDisplay().getRotation()*90;int angle=(info.orientation-rotation+360)%360;camera.setDisplayOrientation(angle);Camera.Size s=camera.getParameters().getPreviewSize();int vw=preview.getWidth(),vh=preview.getHeight();float ratio=(angle%180==0)?(float)s.width/s.height:(float)s.height/s.width;int sw=vw,sh=(int)(vw/ratio);if(sh<vh){sh=vh;sw=(int)(vh*ratio);}FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(sw,sh,Gravity.CENTER);surface.setLayoutParams(lp);camera.setPreviewDisplay(surface.getHolder());camera.setPreviewCallback((data,c)->onFrame(data,c));camera.startPreview();scanning=true;}catch(Exception e){stopCamera();toast("Камера недоступна. Проверь разрешение и закрой другие приложения камеры.");}}
 void onFrame(byte[] data,Camera c){long now=SystemClock.elapsedRealtime();if(!scanning||busy||now-lastFrame<350)return;busy=true;lastFrame=now;Camera.Size s;try{s=c.getParameters().getPreviewSize();}catch(Exception e){busy=false;return;}byte[] copy=data.clone();worker.execute(()->{try{String value=QrEngine.decode(new PlanarYUVLuminanceSource(copy,s.width,s.height,0,0,s.width,s.height,false));main.post(()->{if(scanning&&resumed&&page==0){scanning=false;showResult(value,true);}});}catch(Exception ignored){}finally{busy=false;}});}
 void toggleTorch(){if(camera==null){toast("Сначала включи камеру");return;}try{Camera.Parameters p=camera.getParameters();List<String> modes=p.getSupportedFlashModes();if(modes==null||!modes.contains(Camera.Parameters.FLASH_MODE_TORCH)){toast("Фонарик недоступен");return;}torch=!torch;p.setFlashMode(torch?Camera.Parameters.FLASH_MODE_TORCH:Camera.Parameters.FLASH_MODE_OFF);camera.setParameters(p);}catch(Exception e){toast("Не удалось включить фонарик");}}
 void stopCamera(){scanning=false;torch=false;if(camera!=null){try{camera.setPreviewCallback(null);camera.stopPreview();camera.release();}catch(Exception ignored){}camera=null;}}
 public void surfaceCreated(SurfaceHolder h){ready=true;if(cameraRequested)ensureCamera();}public void surfaceChanged(SurfaceHolder h,int f,int w,int height){ready=true;}public void surfaceDestroyed(SurfaceHolder h){ready=false;stopCamera();}
 @Override protected void onResume(){super.onResume();resumed=true;if(cameraRequested)main.post(()->ensureCamera());}@Override protected void onPause(){resumed=false;stopCamera();super.onPause();}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}@Override protected void onSaveInstanceState(Bundle b){b.putString("draft",input!=null?input.getText().toString():draft);super.onSaveInstanceState(b);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==20&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)ensureCamera();else if(r==20)toast("Без доступа к камере можно сканировать картинки");}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(page==0)main.post(()->ensureCamera());return;}Uri uri=data.getData();if(r==11&&generated!=null){try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();generated.compress(Bitmap.CompressFormat.PNG,100,out);toast("QR сохранён");}catch(Exception e){toast("Не удалось сохранить файл");}}else if(r==10){resultShowing=true;toast("Распознаю QR…");worker.execute(()->{try{BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,opts);}opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>2400||opts.outHeight/opts.inSampleSize>2400)opts.inSampleSize*=2;opts.inJustDecodeBounds=false;Bitmap bmp;try(InputStream in=getContentResolver().openInputStream(uri)){bmp=BitmapFactory.decodeStream(in,null,opts);}if(bmp==null)throw new IOException();int w=bmp.getWidth(),h=bmp.getHeight();int[] px=new int[w*h];bmp.getPixels(px,0,w,0,0,w,h);bmp.recycle();String value=QrEngine.decode(new RGBLuminanceSource(w,h,px));main.post(()->{if(!isFinishing())showResult(value,true);});}catch(Exception e){main.post(()->{resultShowing=false;toast("QR не найден. Выбери чёткую картинку с кодом.");ensureCamera();});}});}}
 void toast(String t){Toast.makeText(this,t,Toast.LENGTH_LONG).show();}
 class Reticle extends View{Paint p=new Paint(3);Reticle(){super(MainActivity.this);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){float size=Math.min(getWidth(),getHeight())*.72f,l=(getWidth()-size)/2,t=(getHeight()-size)/2,r=l+size,b=t+size;p.setColor(0x65000000);p.setStyle(Paint.Style.FILL);c.drawRect(0,0,getWidth(),t,p);c.drawRect(0,b,getWidth(),getHeight(),p);c.drawRect(0,t,l,b,p);c.drawRect(r,t,getWidth(),b,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(4));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(ACC);float d=dp(25);c.drawLine(l,t,l+d,t,p);c.drawLine(l,t,l,t+d,p);c.drawLine(r,t,r-d,t,p);c.drawLine(r,t,r,t+d,p);c.drawLine(l,b,l+d,b,p);c.drawLine(l,b,l,b-d,p);c.drawLine(r,b,r-d,b,p);c.drawLine(r,b,r,b-d,p);}}
